func _run_tests() -> void:
	var level := await instantiate_main_scene()
	if not check("level", level != null, "La scena principale level.tscn deve istanziarsi senza errori"):
		return

	var player := find_by_name(level, "Player") as CharacterBody2D
	if not check("player", player != null, "Nella scena deve esserci il nodo Player"):
		return

	player.global_position = Vector2(200.0, 150.0)
	player.set("health", 80)
	call_if_exists(player, "add_key")
	call_if_exists(player, "add_key")
	call_if_exists(player, "unlock_door", ["door_north"])
	call_if_exists(player, "unlock_door", ["door_east"])
	await wait_frames(2)

	var keys_before: int = int(player.get("keys"))
	check("keys_added", keys_before == 2, "add_key() chiamato due volte deve portare le chiavi a 2 (trovate: %d)" % keys_before)

	var doors_before = player.get("unlocked_doors")
	var count_before: int = doors_before.size() if typeof(doors_before) == TYPE_ARRAY else 0
	check("doors_added", count_before == 2, "unlock_door() deve registrare 2 porte (trovate: %d)" % count_before)

	SaveSystem.save_state(player)
	await wait_frames(2)

	player.global_position = Vector2.ZERO
	player.set("health", 100)
	player.set("keys", 0)
	player.set("unlocked_doors", [])
	await wait_frames(2)

	SaveSystem.load_state(player)
	await wait_frames(2)

	var dist: float = player.global_position.distance_to(Vector2(200.0, 150.0))
	check("pos_ok", dist < 1.0, "La posizione salvata deve essere ripristinata correttamente (distanza: %.1f)" % dist)
	check("health_ok", int(player.get("health")) == 80, "La salute salvata deve tornare a 80")
	check("keys_loaded", int(player.get("keys")) == 2, "Le chiavi salvate devono tornare a 2 (trovate: %d)" % int(player.get("keys")))

	var doors_after = player.get("unlocked_doors")
	var doors_arr: Array = doors_after if typeof(doors_after) == TYPE_ARRAY else []
	var contains_both: bool = doors_arr.has("door_north") and doors_arr.has("door_east")
	check("doors_loaded", contains_both and doors_arr.size() == 2, "L'array unlocked_doors deve contenere [\"door_north\", \"door_east\"] dopo il caricamento")
