extends Node

const SAVE_PATH: String = "user://dungeon_save.json"


static func save_state(player: Node2D) -> void:
	var data: Dictionary = {
		"player": {
			"x": player.global_position.x,
			"y": player.global_position.y,
			"health": int(player.get("health")) if player.get("health") != null else 100
		}
	}
	var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file != null:
		file.store_string(JSON.stringify(data))
		file.close()


static func load_state(player: Node2D) -> void:
	if not FileAccess.file_exists(SAVE_PATH):
		return
	var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
	if file == null:
		return
	var text := file.get_as_text()
	file.close()
	var json := JSON.new()
	if json.parse(text) != OK:
		return
	var data: Dictionary = json.data
	if data.has("player"):
		var p: Dictionary = data["player"]
		player.global_position = Vector2(float(p.get("x", 0.0)), float(p.get("y", 0.0)))
		if player.get("health") != null:
			player.set("health", int(p.get("health", 100)))
